import java.sql.*;import java.util.*;import model.CaseReport;
public class CaseReportDao {
 public CaseReport latest(String caseId)throws SQLException{String q="SELECT * FROM case_reports WHERE case_id=? ORDER BY id DESC LIMIT 1";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setString(1,caseId);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 public long create(String caseId,String type,String title,String content,String by)throws SQLException{String q="INSERT INTO case_reports(case_id,report_type,title,content,status,created_by) VALUES(?,?,?,?, 'DRAFT',?)";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,caseId);p.setString(2,type);p.setString(3,title);p.setString(4,content);p.setString(5,by);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return r.next()?r.getLong(1):0;}}}
 public void updateStatus(long id,String status,String approver)throws SQLException{String q="UPDATE case_reports SET status=?,approved_by=CASE WHEN ?='APPROVED' THEN ? ELSE approved_by END,updated_at=CURRENT_TIMESTAMP WHERE id=?";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setString(1,status);p.setString(2,status);p.setString(3,approver);p.setLong(4,id);p.executeUpdate();}}
 private CaseReport map(ResultSet r)throws SQLException{return new CaseReport(r.getLong("id"),r.getString("case_id"),r.getString("report_type"),r.getString("title"),r.getString("content"),r.getString("status"),r.getString("created_by"),r.getString("approved_by"),r.getString("created_at"),r.getString("updated_at"));}
}
